 draw(){const c=this.polarity===1?COLORS.positive:COLORS.negative,pulse=.7+.3*Math.sin(time*.16+this.arcPhase);ctx.save();ctx.shadowColor=c;ctx.shadowBlur=20+10*pulse;ctx.fillStyle='#273343';ctx.fillRect(this.x,this.y,this.w,this.h);ctx.fillStyle='#101923';ctx.fillRect(this.x+4,this.y+3,this.w-8,this.h-6);ctx.fillStyle='#65788b';for(let x=this.x+9;x<this.x+this.w-5;x+=28){ctx.fillRect(x,this.y+5,12,2);ctx.fillRect(x,this.y+this.h-7,12,2)}ctx.strokeStyle=c;ctx.lineWidth=2;ctx.globalAlpha=.9;ctx.strokeRect(this.x+.5,this.y+.5,this.w-1,this.h-1);ctx.strokeStyle=c;ctx.shadowBlur=15;ctx.lineWidth=1.5;for(let i=0;i<5;i++){const x=this.x+((i*53+time*1.7+this.arcPhase*8)%this.w);ctx.globalAlpha=.3+.65*((Math.sin(time*.27+i*2.3+this.arcPhase)+1)/2);ctx.beginPath();ctx.moveTo(x,this.y-5);ctx.lineTo(x+((i%2)?6:-5),this.y+this.h*.45);ctx.lineTo(x+((i%2)?-4:7),this.y+this.h+5);ctx.stroke()}ctx.globalAlpha=1;ctx.fillStyle=c;ctx.shadowBlur=12;ctx.fillRect(this.x+this.w*.44,this.y+this.h*.42,this.w*.12,3);ctx.restore()}
