const DEMO_START={x:420,y:330};
const DEMO_REFLECTORS=[{x1:555,y1:280,x2:605,y2:310},{x1:255,y1:340,x2:245,y2:400}];
const DEMO_NODE={x:760,y:365,radius:98,polarity:1};
const DEMO_PRISM={x:1020,y:330};
const DEMO_PLATFORM={x:0,y:510,w:170,h:14,center:790};
const DEMO_FIELD={x:405,y:324,w:158,h:96};
let demoEvent='',demoEventLife=0,demoEventX=0,demoEventY=0,demoPrismPulse=0,demoPlatformPulse=0,demoRouteReady=false;
function cubic(a,b,c,d,t){const u=1-t;return {x:u*u*u*a.x+3*u*u*t*b.x+3*u*t*t*c.x+t*t*t*d.x,y:u*u*u*a.y+3*u*u*t*b.y+3*u*t*t*c.y+t*t*t*d.y}}
function makeDemoLeg(index){const p={x:demoX,y:demoY};let c1,c2,end,duration,dynamic=false;
 if(index===0){c1={x:p.x+55,y:p.y-20};c2={x:520,y:290};end={x:580,y:295};duration=72}
 else if(index===1){c1={x:615,y:360};c2={x:695,y:468};end={x:765,y:455};duration=57}
 else if(index===2){c1={x:830,y:488};c2={x:900,y:306};end={x:DEMO_PRISM.x,y:DEMO_PRISM.y};duration=70}
 else if(index===3){dynamic=true;end={x:DEMO_PLATFORM.center,y:DEMO_PLATFORM.y-14};c1={x:p.x-46,y:p.y-4};c2={x:end.x+65,y:DEMO_PLATFORM.y-52};duration=64}
 else if(index===4){c1={x:p.x-30,y:p.y-66};c2={x:650,y:344};end={x:560,y:380};duration=56}
 else if(index===5){c1={x:510,y:355};c2={x:390,y:350};end={x:315,y:372};duration=48}
 else if(index===6){c1={x:285,y:372};c2={x:273,y:390};end={x:250,y:370};duration=28}
 else {c1={x:290,y:350};c2={x:365,y:345};end={x:DEMO_START.x,y:DEMO_START.y};duration=55}
 return {index,p0:p,c1,c2,p1:end,duration,t:0,dynamic};
}
function setDemoEvent(label,x=demoX,y=demoY){demoEvent=label;demoEventX=x;demoEventY=y;demoEventLife=2.5}
function resetDemoRoute(){demoX=DEMO_START.x;demoY=DEMO_START.y;demoPolarity=1;demoTrail=[];demoLegIndex=0;demoLeg=makeDemoLeg(0);demoRouteReady=true;demoEvent='';demoEventLife=0;demoPrismPulse=0;demoPlatformPulse=0}
function nextDemoLeg(){const justFinished=demoLegIndex;
 if(justFinished===0)setDemoEvent('ELECTRODE REFLECTION');
 if(justFinished===1)setDemoEvent('REPULSOR FIELD DEFLECTION');
 if(justFinished===2){demoPolarity*=-1;demoPrismPulse=.8;setDemoEvent('PRISM · POLARITY '+(demoPolarity>0?'+':'−')+' / VX REVERSED')}
 if(justFinished===3){demoPlatformPulse=.85;setDemoEvent('MOVING PLATFORM CONTACT')}
 if(justFinished===5)setDemoEvent('DIRECTIONAL FIELD · RETURN PASS');
 if(justFinished===6)setDemoEvent('RETURN ELECTRODE · REFLECTION');
 if(justFinished===7)setDemoEvent('ROUTE REPEATS');
 demoLegIndex=(justFinished+1)%8;demoLeg=makeDemoLeg(demoLegIndex);
}
function updateDemo(dt){demoTime+=dt/60;if(!demoRouteReady)resetDemoRoute();DEMO_PLATFORM.x=DEMO_PLATFORM.center+Math.sin(demoTime*.42)*24;demoEventLife=Math.max(0,demoEventLife-dt/60);demoPrismPulse=Math.max(0,demoPrismPulse-dt/46);demoPlatformPulse=Math.max(0,demoPlatformPulse-dt/36);const leg=demoLeg;if(leg.dynamic){leg.p1.x=DEMO_PLATFORM.x+DEMO_PLATFORM.w/2;leg.p1.y=DEMO_PLATFORM.y-10;leg.c2.x=leg.p1.x+65;leg.c2.y=DEMO_PLATFORM.y-52}const oldX=demoX,oldY=demoY;leg.t=Math.min(1,leg.t+dt/leg.duration);const q=cubic(leg.p0,leg.c1,leg.c2,leg.p1,leg.t);demoX=q.x;demoY=q.y;demoVx=demoX-oldX;demoVy=demoY-oldY;if(leg.t>=1){demoX=leg.p1.x;demoY=leg.p1.y;nextDemoLeg()}demoTrail.push({x:demoX,y:demoY,polarity:demoPolarity});if(demoTrail.length>30)demoTrail.shift()}
