class PhasePrism{constructor(d){Object.assign(this,d);this.cool=0}update(dt){this.cool=Math.max(0,this.cool-dt)}collides(p){return Math.abs(p.x+p.size/2-this.x)<22&&Math.abs(p.y+p.size/2-this.y)<25}draw(){const pulse=1+Math.sin(time*.09+this.x)*.12;ctx.save();ctx.translate(this.x,this.y);ctx.rotate(Math.PI/4+time*.012);ctx.shadowColor='#b9a0ff';ctx.shadowBlur=22;ctx.fillStyle='rgba(116,78,255,.22)';ctx.strokeStyle='#e7d9ff';ctx.lineWidth=2;ctx.fillRect(-12*pulse,-12*pulse,24*pulse,24*pulse);ctx.strokeRect(-12*pulse,-12*pulse,24*pulse,24*pulse);ctx.strokeStyle='#8dfbff';ctx.beginPath();ctx.moveTo(-7,0);ctx.lineTo(7,0);ctx.moveTo(0,-7);ctx.lineTo(0,7);ctx.stroke();ctx.restore()}}
class RotaryLaser{constructor(d){Object.assign(this,d);this.angle=d.angle||0;this.omega=d.omega||.01}update(dt){this.angle+=this.omega*dt}ends(){return [{x:this.x,y:this.y},{x:this.x+Math.cos(this.angle)*this.length,y:this.y+Math.sin(this.angle)*this.length}]}collides(p){const [a,b]=this.ends(),cx=p.x+p.size/2,cy=p.y+p.size/2,dx=b.x-a.x,dy=b.y-a.y,t=Math.max(0,Math.min(1,((cx-a.x)*dx+(cy-a.y)*dy)/(dx*dx+dy*dy))),qx=a.x+t*dx,qy=a.y+t*dy;return Math.hypot(cx-qx,cy-qy)<p.size*.58}draw(){const [a,b]=this.ends(),c=this.p===1?COLORS.positive:COLORS.negative;ctx.save();ctx.lineCap='round';ctx.strokeStyle=c;ctx.shadowColor=c;ctx.shadowBlur=22;ctx.globalAlpha=.22;ctx.lineWidth=15;ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke();ctx.globalAlpha=.9;ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke();ctx.strokeStyle='#fff';ctx.globalAlpha=.75;ctx.lineWidth=1;ctx.stroke();ctx.fillStyle='#111a2a';ctx.shadowBlur=15;ctx.beginPath();ctx.arc(a.x,a.y,10,0,Math.PI*2);ctx.fill();ctx.strokeStyle=c;ctx.lineWidth=2;ctx.stroke();ctx.restore()}}
function emitSparks(x,y){for(let i=0;i<6;i++){const a=Math.random()*Math.PI*2;electricSparks.push({x,y,vx:Math.cos(a)*(2+Math.random()*4),vy:Math.sin(a)*(2+Math.random()*4),life:.7+Math.random()*.25})}playBreakout()}
function detachMagnetic(down=false){if(!player.magneticPlate)return false;const face=player.magneticFace,plate=player.magneticPlate;player.magneticPlate=null;player.magneticFace=null;player.support=null;player.grounded=false;player.dropThrough=down&&face==='top'?plate:null;player.vy=down?7:(face==='bottom'?10.5:-10.5);player.vx+=(player.x+player.size/2<plate.x+plate.w/2?-1:1)*2.5;emitSparks(player.x+player.size/2,player.y+player.size/2);return true}

