function makeSectorThumbnail(level){if(sectorThumbnailCache.has(level.id))return sectorThumbnailCache.get(level.id);const c=document.createElement('canvas');c.width=160;c.height=90;const q=c.getContext('2d');q.fillStyle='#0a1114';q.fillRect(0,0,160,90);q.strokeStyle='rgba(127,151,145,.09)';for(let x=0;x<160;x+=20){q.beginPath();q.moveTo(x,0);q.lineTo(x,90);q.stroke()}for(let y=0;y<90;y+=18){q.beginPath();q.moveTo(0,y);q.lineTo(160,y);q.stroke()}for(const z of level.gravityZones||[]){q.fillStyle='rgba(139,175,158,.09)';q.fillRect(z.x/8,z.y/8,z.w/8,z.h/8);q.strokeStyle='rgba(153,185,165,.38)';q.setLineDash([2,2]);q.strokeRect(z.x/8,z.y/8,z.w/8,z.h/8);q.setLineDash([])}for(const z of level.voidZones||[]){q.fillStyle='rgba(100,77,115,.24)';q.fillRect(z.x/8,z.y/8,z.w/8,z.h/8);q.strokeStyle='rgba(158,129,170,.35)';q.strokeRect(z.x/8,z.y/8,z.w/8,z.h/8)}for(const s of level.platforms){const x=Array.isArray(s)?s[0]:s.x,y=Array.isArray(s)?s[1]:s.y,w=Array.isArray(s)?s[2]:s.w,h=Array.isArray(s)?s[3]:s.h,p=Array.isArray(s)?s[4]:(s.p??0);q.fillStyle=p===1?'rgba(126,177,170,.8)':p===-1?'rgba(179,143,115,.8)':'rgba(115,132,133,.65)';q.fillRect(x/8,y/8,Math.max(1,w/8),Math.max(1,h/8))}for(const l of level.lasers||[]){q.strokeStyle='rgba(196,153,139,.78)';q.lineWidth=1.5;q.beginPath();if(l.angle!=null){const len=l.length||Math.hypot(l.w||0,l.h||0);q.moveTo(l.x/8,l.y/8);q.lineTo((l.x+Math.cos(l.angle)*len)/8,(l.y+Math.sin(l.angle)*len)/8)}else{q.moveTo(l.x/8,l.y/8);q.lineTo(l.x/8,(l.y+l.h)/8)}q.stroke()}for(const g of level.pulsarGates||[]){q.fillStyle='rgba(194,145,135,.8)';q.fillRect(g.x/8,g.y/8,Math.max(1,g.w/8),g.h/8)}for(const n of level.nodes||[]){q.fillStyle='#c3d0c7';q.beginPath();q.arc(n.x/8,n.y/8,2,0,Math.PI*2);q.fill()}for(const p of level.prisms||[]){q.strokeStyle='#c7bdcf';q.strokeRect(p.x/8-2,p.y/8-2,4,4)}if(level.portal){q.strokeStyle='#b4c8bd';q.lineWidth=1;q.beginPath();q.ellipse((level.portal[0]+27)/8,(level.portal[1]+44)/8,3.3,5.5,0,0,Math.PI*2);q.stroke()}q.strokeStyle='rgba(177,195,187,.48)';q.strokeRect(.5,.5,159,89);sectorThumbnailCache.set(level.id,c);return c}
function drawSectorSelect(){ctx.save();ctx.fillStyle='rgba(5,10,14,.80)';ctx.fillRect(18,28,1244,666);ctx.strokeStyle='rgba(129,154,148,.28)';ctx.strokeRect(18.5,28.5,1243,665);ctx.textAlign='left';ctx.fillStyle='#dce7e0';ctx.font='600 22px ui-monospace,monospace';ctx.fillText('SECTOR SELECT',38,73);ctx.fillStyle='#879992';ctx.font='10px ui-monospace,monospace';ctx.fillText('SELECT A TEST CONFIGURATION',39,95);drawRule(38,111,1204);for(let col=0;col<5;col++){const x=30+col*244,biome=BIOMES[col];ctx.fillStyle=biome.color;ctx.font='10px ui-monospace,monospace';ctx.textAlign='left';ctx.fillText(biome.name,x+3,146);drawRule(x,154,226,'rgba(142,164,155,.2)');for(let row=0;row<3;row++){const i=col*3+row;if(i>=LEVELS.length)continue;const level=LEVELS[i],y=166+row*164,w=226,h=148,completed=completedSectorIds.has(level.id),focused=i===sectorFocus||i===hoverSector;ctx.fillStyle=focused?'rgba(25,37,38,.97)':'rgba(12,20,23,.9)';ctx.fillRect(x,y,w,h);ctx.strokeStyle=focused?'rgba(159,188,174,.75)':'rgba(105,126,126,.28)';ctx.strokeRect(x+.5,y+.5,w-1,h-1);if(focused){ctx.fillStyle=biome.color;ctx.fillRect(x,y,3,h)}ctx.fillStyle='#cbd6d0';ctx.font='bold 13px ui-monospace,monospace';ctx.fillText(String(i+1).padStart(2,'0'),x+14,y+25);ctx.fillStyle=completed?'#a9c4af':'#7f8f8a';ctx.font='9px ui-monospace,monospace';ctx.textAlign='right';ctx.fillText(completed?'CLEARED':'NOT CLEARED',x+w-12,y+24);ctx.textAlign='left';ctx.fillStyle='#e0e8e3';ctx.font='11px ui-monospace,monospace';ctx.fillText(level.name,x+14,y+48);const thumb=makeSectorThumbnail(level);ctx.drawImage(thumb,x+126,y+61,88,50);ctx.fillStyle='#84958e';ctx.font='8px ui-monospace,monospace';ctx.fillText('LAYOUT',x+14,y+82);ctx.fillStyle='rgba(144,165,155,.44)';ctx.fillRect(x+14,y+98,95,1);ctx.fillStyle='#99aaa2';ctx.font='9px ui-monospace,monospace';ctx.fillText('SECTOR '+String(i+1).padStart(2,'0'),x+14,y+119);if(focused)drawFocusOutline(x,y,w,h)}}drawMenuButton(38,660,110,28,'BACK',menuHover===15,'ESC');ctx.restore()}
function drawPauseMenu(){ctx.save();ctx.fillStyle='rgba(4,8,11,.78)';ctx.fillRect(0,0,W,H);const x=448,y=190,w=384,h=340;ctx.fillStyle='rgba(10,17,20,.97)';ctx.fillRect(x,y,w,h);ctx.strokeStyle='rgba(143,169,159,.45)';ctx.strokeRect(x+.5,y+.5,w-1,h-1);ctx.textAlign='left';ctx.fillStyle='#dfe8e3';ctx.font='600 19px ui-monospace,monospace';ctx.fillText('PAUSED',x+28,y+42);drawRule(x+28,y+59,w-56);const labels=['RESUME','RESTART SECTOR','SECTOR SELECT','MAIN MENU'];labels.forEach((label,i)=>{const bx=x+28,by=y+78+i*55,bw=w-56;drawMenuButton(bx,by,bw,42,label,pauseFocus===i||menuHover===i,i===0?'ENTER':'');if(pauseFocus===i)drawFocusOutline(bx,by,bw,42)});ctx.restore()}
function drawVictory(){ctx.save();ctx.fillStyle='rgba(4,8,11,.78)';ctx.fillRect(0,0,W,H);const x=420,y=169,w=440,h=390;ctx.fillStyle='rgba(10,17,20,.97)';ctx.fillRect(x,y,w,h);ctx.strokeStyle='rgba(143,169,159,.42)';ctx.strokeRect(x+.5,y+.5,w-1,h-1);ctx.textAlign='left';ctx.fillStyle='#e2ebe5';ctx.font='600 22px ui-monospace,monospace';ctx.fillText(resultKind==='campaign'?'CAMPAIGN COMPLETE':resultKind==='final'?'FINAL SECTOR CLEARED':'SECTOR CLEARED',x+30,y+52);ctx.fillStyle='#9eafa7';ctx.font='11px ui-monospace,monospace';ctx.fillText('SECTORS CLEARED  '+completedSectorIds.size+' / '+REQUIRED_SECTOR_IDS.size,x+30,y+82);ctx.fillText('CURRENT RUN  ·  DEATHS '+deaths+'  ·  TIME '+Math.floor(totalFrames/60)+'s',x+30,y+102);drawRule(x+30,y+119,w-60);const buttons=resultKind==='sector'||resultKind==='campaign'?[['CONTINUE',0],['SECTOR SELECT',1],['NEW RUN',2],['MAIN MENU',3]]:[['SECTOR SELECT',0],['NEW RUN',1],['MAIN MENU',2]];buttons.forEach(([label,i])=>{const bx=x+30,by=y+138+i*55,bw=w-60;drawMenuButton(bx,by,bw,42,label,resultFocus===i||menuHover===i);if(resultFocus===i)drawFocusOutline(bx,by,bw,42)});ctx.restore()}
function drawPortalWarp(){if(!warp)return;const u=Math.min(1,warp.elapsed/warp.duration);ctx.save();ctx.fillStyle='rgba(4,2,18,'+(0.1+u*.34)+')';ctx.fillRect(0,76,W,H-76);const radius=70+u*580;const flash=ctx.createRadialGradient(warp.centerX,warp.centerY,0,warp.centerX,warp.centerY,radius);flash.addColorStop(0,'rgba(245,220,255,'+(u>.75?(u-.75)*2.8:.18)+')');flash.addColorStop(.22,'rgba(176,38,255,'+(u*.18)+')');flash.addColorStop(1,'rgba(30,10,55,0)');ctx.fillStyle=flash;ctx.fillRect(0,76,W,H-76);ctx.restore()}
function drawPlayer(){const p=player;for(let i=1;i<p.trail.length;i++){const a=p.trail[i-1],b=p.trail[i],prev=p.trail[Math.max(0,i-2)],next=p.trail[Math.min(p.trail.length-1,i+1)];ctx.globalAlpha=i/p.trail.length*.22;ctx.strokeStyle=b.color;ctx.lineWidth=2+i*.1;ctx.shadowBlur=10;ctx.shadowColor=b.color;ctx.beginPath();ctx.moveTo(prev.x,prev.y);ctx.quadraticCurveTo(a.x,a.y,(a.x+b.x)/2,(a.y+b.y)/2);ctx.quadraticCurveTo(b.x,b.y,(b.x+next.x)/2,(b.y+next.y)/2);ctx.stroke()}ctx.globalAlpha=1;ctx.shadowBlur=0;ctx.save();ctx.translate(p.x+p.size/2,p.y+p.size/2);ctx.scale(p.scale,p.scale);ctx.translate(-(p.x+p.size/2),-(p.y+p.size/2));ctx.shadowBlur=23;ctx.shadowColor=p.color;ctx.fillStyle=p.color;ctx.fillRect(p.x,p.y,p.size,p.size);ctx.strokeStyle='#f4fdff';ctx.lineWidth=2;ctx.strokeRect(p.x+1,p.y+1,p.size-2,p.size-2);ctx.fillStyle='#071018';ctx.fillRect(p.x+5,p.y+5,18,18);ctx.fillStyle=p.color;ctx.font='bold 15px ui-monospace,monospace';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(p.polarity>0?'+':'−',p.x+14,p.y+14);ctx.restore()}
function render(now){if(titleScreen||mainMenu||levelSelect){drawDemoChamber();drawDemoParticle();if(titleScreen)drawTitleScreen();else if(levelSelect)drawSectorSelect();else drawMainMenu();return}if(pauseMenu&&pauseBackdrop){ctx.drawImage(pauseBackdrop,0,0,W,H);drawPauseMenu();return}drawBackdrop();zones.forEach(z=>z.draw(player.polarity));voidZones.forEach(z=>z.draw());nodes.forEach(n=>n.draw(player.polarity));platforms.forEach(p=>p.draw());lasers.forEach(l=>l.draw());prisms.forEach(o=>o.draw());rotaryLasers.forEach(o=>o.draw());electricSparks.forEach(s=>{ctx.save();ctx.globalAlpha=Math.max(0,s.life);ctx.strokeStyle='#afffff';ctx.shadowColor='#5beaff';ctx.shadowBlur=12;ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(s.x,s.y);ctx.lineTo(s.x+s.vx*2,s.y+s.vy*.35);ctx.lineTo(s.x+s.vx*3,s.y+s.vy*2);ctx.stroke();ctx.restore()});pulsarGates.forEach(g=>g.draw());shardList.forEach(s=>s.draw());portal.draw(shardList.every(s=>s.collected));particles.forEach(q=>{ctx.globalAlpha=q.life;ctx.fillStyle=q.color;ctx.shadowBlur=10;ctx.shadowColor=q.color;ctx.fillRect(q.x,q.y,q.size,q.size)});ringPulses.forEach(r=>{ctx.globalAlpha=r.life;ctx.strokeStyle=COLORS.positive;ctx.shadowColor=COLORS.positive;ctx.shadowBlur=20;ctx.lineWidth=3;ctx.beginPath();ctx.arc(r.x,r.y,r.r,0,Math.PI*2);ctx.stroke();ctx.globalAlpha=r.life*.8;ctx.strokeStyle=COLORS.negative;ctx.beginPath();ctx.arc(r.x,r.y,r.r*.72,0,Math.PI*2);ctx.stroke()});ctx.globalAlpha=1;ctx.shadowBlur=0;drawPlayer();if(!pauseMenu&&!levelSelect&&!victory&&performance.now()<lockedUntil){ctx.save();ctx.font='bold 12px ui-monospace,monospace';ctx.textAlign='center';ctx.fillStyle='#00f0ff';ctx.globalAlpha=.55;ctx.fillText('LOCKED',player.x+11,player.y-8);ctx.fillStyle='#ff3658';ctx.globalAlpha=.9;ctx.shadowColor='#ff174c';ctx.shadowBlur=12;ctx.fillText('LOCKED',player.x+16,player.y-10);ctx.restore()}if(!pauseMenu&&!levelSelect&&!victory)drawHud();if(levelSelect)drawLevelSelect();else if(pauseMenu)drawPauseMenu();else if(victory)drawVictory();if(warp)drawPortalWarp();if(screenFlash>0){const f=screenFlash/14;const g=ctx.createRadialGradient(W/2,H/2,4,W/2,H/2,700);g.addColorStop(0,'rgba(246,220,255,'+(f*.55)+')');g.addColorStop(1,'rgba(176,38,255,0)');ctx.fillStyle=g;ctx.fillRect(0,0,W,H)}}
function frame(currentTime){if(!lastTime)lastTime=currentTime;const dt=Math.min((currentTime-lastTime)/16.667,2.0);lastTime=currentTime;const simDt=dt*(currentTime<slowUntil?.4:1);physics(simDt);tickMusic(dt);render(currentTime);requestAnimationFrame(frame)}
